    for (const p of state.particles) {
      const a = p.life/p.max;
      ctx.fillStyle = p.color;
      ctx.globalAlpha = a;
      ctx.fillRect(p.x-3, p.y-3, 6, 6);
      ctx.globalAlpha = 1;
    }
    // enemies
    for (const e of state.enemies) {
      if (!e.alive) continue;
      const frame = e.moving && Math.floor(e.anim)%2===0 ? 'enemy_walk_1' : 'enemy_idle';
      drawSprite(frame, e.px, e.py, false);
    }
    // player
    const p = state.player;
    if (p.alive) {
      let frame;
      if (p.dir==='down') frame = p.moving && Math.floor(p.anim)%2===0 ? 'hero_walk_down_1' : (p.moving?'hero_walk_down_2':'hero_idle_down');
      else if (p.dir==='up') frame = p.moving ? 'hero_walk_up_1' : 'hero_idle_up';
      else if (p.dir==='right') frame = p.moving ? 'hero_walk_right_1' : 'hero_idle_right';
      else frame = p.moving ? 'hero_walk_right_1' : 'hero_idle_right';
      const flip = p.dir==='left';
      if (p.invuln>0 && Math.floor(state.frame/4)%2===0) {
        // blink
      } else {
        drawSprite(frame, p.px, p.py, flip);
      }
    }
    ctx.restore();

    // HUD
    document.getElementById('score').textContent = state.score;
    document.getElementById('lives').textContent = state.lives;
    document.getElementById('level').textContent = state.level;
    document.getElementById('bombs').textContent = state.maxBombs;
    document.getElementById('fire').textContent = state.fireRange;

    if (state.over) {
      ctx.fillStyle = 'rgba(0,0,0,0.7)';
      ctx.fillRect(0,0,W,H);
      ctx.fillStyle = '#fff';
      ctx.font = 'bold 48px monospace';
      ctx.textAlign = 'center';
      ctx.fillText('GAME OVER', W/2, H/2);
      ctx.font = '20px monospace';
      ctx.fillText('Press R to restart', W/2, H/2+40);
      ctx.textAlign = 'left';
    }
  }

  function frame() {
    try {
      update(0.016);
      draw();
    } catch (e) { console.error(e); }
    requestAnimationFrame(frame);
  }

  // ---- Init ----
  initLevel(1);
  requestAnimationFrame(frame);
  loadAssets();
})();
</script>
</body></html>
```


GENERATED-SPRITE DRAW CONTRACT — PNG paths were returned above. Every entity that has a generated sprite MUST be drawn with `ctx.drawImage` via `sprite(key)` (or `ASSETS[key]` after `img.decode()`). Replace the seed's procedural player/enemy/piece draw bodies (`fillRect`, `arc`, Unicode glyphs) with drawImage. The seed boilerplate is safe to keep ONLY for canvas sizing, RAF, input map, and HUD plumbing — NOT for entity draw. Procedural shapes are allowed ONLY as a labeled MISSING fallback while an image is still decoding, or for entities with NO generated PNG (grid lines, particles, health bars). `loadAssets()` alone is insufficient — each entity draw path must call drawImage when the sprite is ready.
SELF-CHECK before emitting: every name listed in GENERATED ASSETS must appear in a draw call (`sprite('name')` or `drawImage(ASSETS.name` / `ASSETS['name']`) in this first build — loading without drawing fails the undrawn-art gate.
Expose `window.state = state` (or `window.gameState = state`) after init so behavioral probes can read player position, score, and game flags.
